import type { Metadata } from "next";
import Link from "next/link";
import { createServerSupabase } from "@/lib/supabase/server";
import ProductsManager from "@/components/ProductsManager";
export const metadata:Metadata={title:"Products"};
export default async function ProductsPage(){const supabase=await createServerSupabase();const {data:{user}}=await supabase.auth.getUser();if(!user)return <div className="container py-12">Please log in.</div>;const {data:vendor}=await supabase.from("vendors").select("business_name,is_active").eq("owner_id",user.id).maybeSingle();return <main className="container py-8 sp-page sp-page--vendor-products"><Link className="text-sm underline" href="/dashboard/vendor">← Your shop</Link><h1 className="display mt-4 text-4xl font-bold">Products</h1><p className="muted mt-2">Add and update the items customers can order from {vendor?.business_name||"your shop"}.</p>{!vendor?.is_active?<div className="ticket mt-6"><h2 className="display text-2xl font-bold">Pay GH₵ 150 to go live</h2><p className="mt-2">Once the setup fee clears, you can add products and open your shop.</p><Link className="btn mt-4" href="/dashboard/vendor">Go to overview</Link></div>:<div className="mt-6"><ProductsManager/></div>}</main>}
